import{_ as a,o as e,c as o,ai as s}from"./chunks/framework.C33Uq6m-.js";const m=JSON.parse('{"title":"Cost Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/cost-dashboard.md","filePath":"en/guide/cost-dashboard.md"}'),d={name:"en/guide/cost-dashboard.md"};function r(l,t,i,n,c,h){return e(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="cost-dashboard" tabindex="-1">Cost Dashboard <a class="header-anchor" href="#cost-dashboard" aria-label="Permalink to &quot;Cost Dashboard&quot;">​</a></h1><p>The Cost Dashboard tracks token usage across all your sessions and estimates what the same workload would cost on commercial cloud APIs.</p><p><strong>Sidebar item:</strong> Costs <strong>Route:</strong> <code>/costs</code></p><h2 id="why-track-costs-locally" tabindex="-1">Why Track Costs Locally? <a class="header-anchor" href="#why-track-costs-locally" aria-label="Permalink to &quot;Why Track Costs Locally?&quot;">​</a></h2><p>Ollama runs on your machine at zero cost. But understanding the equivalent cloud cost helps you:</p><ul><li><strong>Quantify savings</strong> — See how much you&#39;re saving by running locally</li><li><strong>Plan capacity</strong> — Understand which models consume the most tokens</li><li><strong>Compare efficiency</strong> — Identify which models give the best output per token</li></ul><h2 id="dashboard-sections" tabindex="-1">Dashboard Sections <a class="header-anchor" href="#dashboard-sections" aria-label="Permalink to &quot;Dashboard Sections&quot;">​</a></h2><h3 id="summary-cards" tabindex="-1">Summary Cards <a class="header-anchor" href="#summary-cards" aria-label="Permalink to &quot;Summary Cards&quot;">​</a></h3><p>Four cards at the top showing:</p><ul><li><strong>Total Tokens</strong> — Sum of all prompt + completion tokens across sessions</li><li><strong>Sessions</strong> — Total number of chat sessions recorded</li><li><strong>Estimated Cost</strong> — What the same usage would cost on cloud APIs</li><li><strong>Avg Cost/Session</strong> — Average estimated cost per session</li></ul><h3 id="token-usage-by-model" tabindex="-1">Token Usage by Model <a class="header-anchor" href="#token-usage-by-model" aria-label="Permalink to &quot;Token Usage by Model&quot;">​</a></h3><p>A horizontal stacked bar chart showing prompt (indigo) and completion (purple) tokens for each model you&#39;ve used. Models are sorted by total token count.</p><h3 id="daily-usage" tabindex="-1">Daily Usage <a class="header-anchor" href="#daily-usage" aria-label="Permalink to &quot;Daily Usage&quot;">​</a></h3><p>A line chart with two axes:</p><ul><li><strong>Left axis</strong> — Total tokens per day (filled area)</li><li><strong>Right axis</strong> — Estimated cost per day (dashed line)</li></ul><p>Hover over any point to see exact values.</p><h3 id="model-breakdown-table" tabindex="-1">Model Breakdown Table <a class="header-anchor" href="#model-breakdown-table" aria-label="Permalink to &quot;Model Breakdown Table&quot;">​</a></h3><p>A detailed table with columns:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td>Model</td><td>The Ollama model name</td></tr><tr><td>Sessions</td><td>Number of chat sessions</td></tr><tr><td>Prompt</td><td>Total prompt tokens</td></tr><tr><td>Completion</td><td>Total completion tokens</td></tr><tr><td>Total</td><td>Combined token count</td></tr><tr><td>Est. Cost</td><td>Estimated cloud-equivalent cost</td></tr><tr><td>Source</td><td>Where the pricing data comes from</td></tr></tbody></table><h2 id="pricing-data" tabindex="-1">Pricing Data <a class="header-anchor" href="#pricing-data" aria-label="Permalink to &quot;Pricing Data&quot;">​</a></h2><p>Pricing is based on equivalent cloud API rates for common model families:</p><table tabindex="0"><thead><tr><th>Model Family</th><th>Input $/1M</th><th>Output $/1M</th><th>Source</th></tr></thead><tbody><tr><td>llama3.2</td><td>$0.04</td><td>$0.04</td><td>Together AI</td></tr><tr><td>llama3.1</td><td>$0.05</td><td>$0.08</td><td>Groq</td></tr><tr><td>gemma3</td><td>$0.10</td><td>$0.10</td><td>Google</td></tr><tr><td>mistral</td><td>$0.25</td><td>$0.25</td><td>Mistral</td></tr><tr><td>deepseek-r1</td><td>$0.55</td><td>$2.19</td><td>DeepSeek</td></tr><tr><td>phi4</td><td>$0.07</td><td>$0.14</td><td>Azure</td></tr><tr><td>qwen2.5</td><td>$0.15</td><td>$0.15</td><td>Alibaba</td></tr></tbody></table><p>Models not in the pricing table fall back to a generic estimate of $0.10/$0.10 per 1M tokens, labeled as &quot;Estimated&quot;.</p><div class="info custom-block"><p class="custom-block-title">These are estimates</p><p>All costs shown are what equivalent usage would cost on cloud APIs. Ollama runs locally at no cost. The pricing data is a static snapshot and may not reflect current cloud pricing.</p></div><h2 id="data-source" tabindex="-1">Data Source <a class="header-anchor" href="#data-source" aria-label="Permalink to &quot;Data Source&quot;">​</a></h2><p>The cost dashboard derives all data from the metrics store — the same session metrics recorded during chat. No additional tracking or storage is needed. The cost store is purely computed (reactive) and recalculates automatically when new sessions are recorded.</p>',26)])])}const p=a(d,[["render",r]]);export{m as __pageData,p as default};
